select jsonb_build_object('checked_at',clock_timestamp(),'works',(select jsonb_agg(to_jsonb(w) order by id) from public.works w where id in(2999,1907,1342,1399,1545,1557,1607,1829,1635,3274,3262,3266,1362,1472,3278,3291,2993,3494,3368,2172,3257,3267)),'authors',(select jsonb_agg(to_jsonb(a) order by id) from public.authors a where id in(select author_id from public.works where id in(2999,1907,1342,1399,1545,1557,1607,1829,1635,3274,3262,3266,1362,1472,3278,3291,2993,3494,3368,2172,3257,3267))),'editions',(select jsonb_agg(to_jsonb(e) order by id) from public.editions e where work_id in(2999,1907,1342,1399,1545,1557,1607,1829,1635,3274,3262,3266,1362,1472,3278,3291,2993,3494,3368,2172,3257,3267)),'descriptions',(select coalesce(jsonb_agg(to_jsonb(d)),'[]') from public.catalog_work_descriptions d where work_id in(2999,1907,1342,1399,1545,1557,1607,1829,1635,3274,3262,3266,1362,1472,3278,3291,2993,3494,3368,2172,3257,3267)),'metadata',(select coalesce(jsonb_agg(to_jsonb(m)),'[]') from public.catalog_edition_metadata m where work_id in(2999,1907,1342,1399,1545,1557,1607,1829,1635,3274,3262,3266,1362,1472,3278,3291,2993,3494,3368,2172,3257,3267))) as preflight;
